def solve(candidates, min_slice, max_p95, max_memory):
    from fractions import Fraction
    best = None
    for name, p95, memory, quality, cost, eligible in candidates:
        if not eligible or p95 > max_p95 or memory > max_memory:
            continue
        if any(slice_name not in quality or quality[slice_name] < floor for slice_name, floor in min_slice.items()):
            continue
        rank = Fraction(cost, eligible), p95, name
        if best is None or rank < best:
            best = rank
    return None if best is None else best[2]
